diff --git a/gin.go b/gin.go
index a160727..4986f67 100644
--- a/gin.go
+++ b/gin.go
@@ -772,7 +772,8 @@ func (engine *Engine) handleHTTPRequest(c *Context) {
 			if tree.method == httpMethod {
 				continue
 			}
-			if value := tree.root.getValue(rPath, nil, c.skippedNodes, unescape); value.handlers != nil {
+			skippedNodes := make([]skippedNode, 0, engine.maxSections)
+			if value := tree.root.getValue(rPath, nil, &skippedNodes, unescape); value.handlers != nil {
 				allowed = append(allowed, tree.method)
 			}
 		}
diff --git a/response_writer.go b/response_writer.go
index 8e2d8b3..a00bc7a 100644
--- a/response_writer.go
+++ b/response_writer.go
@@ -118,10 +118,11 @@ func (w *responseWriter) Hijack() (net.Conn, *bufio.ReadWriter, error) {
 	if !ok {
 		return nil, nil, http.ErrNotSupported
 	}
-	if w.size < 0 {
+	conn, rw, err := hijacker.Hijack()
+	if err == nil && w.size < 0 {
 		w.size = 0
 	}
-	return hijacker.Hijack()
+	return conn, rw, err
 }

 // CloseNotify implements the http.CloseNotifier interface.
